'use client';

import type { HTMLAttributes, JSX, ReactNode, Ref } from 'react';
import styles from './empty-state.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

export interface EmptyStateProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /** Decorative icon, shown in a tinted tile above the title. */
  icon?: ReactNode;
  title: ReactNode;
  /** One or two sentences: why it's empty and what to do next. */
  description?: ReactNode;
  /** Primary next step, usually a Button (or a Button and a Link). */
  action?: ReactNode;
  /** `sm` for tables, popovers and cards; `md` for whole pages or sections. */
  size?: 'sm' | 'md';
  /** Heading level of the title. */
  level?: 2 | 3 | 4 | 5 | 6;
  ref?: Ref<HTMLDivElement>;
}

/** What to show when there is nothing to show — no data yet, no results, or nothing left to do. */
export function EmptyState({
  icon,
  title,
  description,
  action,
  size = 'md',
  level = 3,
  className,
  children,
  ...rest
}: EmptyStateProps): JSX.Element {
  const Heading = `h${level}` as const;
  return (
    <div {...rest} data-size={size} className={cx(styles.empty, className)}>
      {icon != null && icon !== false && (
        <div className={styles.icon} aria-hidden="true">
          {icon}
        </div>
      )}
      <div className={styles.text}>
        <Heading className={styles.title}>{title}</Heading>
        {description != null && description !== false && <p className={styles.description}>{description}</p>}
      </div>
      {children}
      {action != null && action !== false && <div className={styles.action}>{action}</div>}
    </div>
  );
}

.empty {
  --_tile: var(--strata-space-12);
  --_glyph: var(--strata-space-6);

  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--strata-space-4);
  inline-size: 100%;
  padding-block: var(--strata-space-12);
  padding-inline: var(--strata-space-6);
  color: var(--strata-color-text-default);
  font-family: var(--strata-font-body);
  text-align: center;
}

.empty[data-size='sm'] {
  --_tile: var(--strata-space-10);
  --_glyph: var(--strata-space-5);

  gap: var(--strata-space-3);
  padding-block: var(--strata-space-8);
  padding-inline: var(--strata-space-4);
}

.icon {
  display: grid;
  flex: none;
  place-items: center;
  inline-size: var(--_tile);
  block-size: var(--_tile);
  /* Follows the brand's container shape, capped so round brands get a squircle, not a coin. */
  border-radius: min(var(--strata-radius-container), 30%);
  background-color: var(--strata-color-surface-sunken);
  box-shadow: inset 0 0 0 1px var(--strata-color-border-subtle);
  color: var(--strata-color-text-subtle);
}

.icon > svg {
  inline-size: var(--_glyph);
  block-size: var(--_glyph);
}

.text {
  display: grid;
  justify-items: center;
  gap: var(--strata-space-1);
  max-inline-size: 100%;
}

.title {
  margin: 0;
  font-family: var(--strata-font-heading);
  font-size: var(--strata-font-size-lg);
  font-weight: var(--strata-font-weight-semibold);
  /* Heading tracking is tuned for display sizes; at lg (16px) and below it closes up word spaces. */
  letter-spacing: 0;
  line-height: var(--strata-line-height-snug);
  text-wrap: balance;
}

.empty[data-size='sm'] .title {
  font-size: var(--strata-font-size-md);
}

.description {
  max-inline-size: 48ch;
  margin: 0;
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  line-height: var(--strata-line-height-normal);
  text-wrap: pretty;
}

.action {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--strata-space-2);
  margin-block-start: var(--strata-space-2);
}

.empty[data-size='sm'] .action {
  margin-block-start: var(--strata-space-1);
}
